    if k == WARD:
        return r == 20 and here() in bushes() and count_units(enemies()) == 0
    return False

@gene('v2', 'start of turn: block set once, then the rule, its goal and target; shared-memory and priority writes')
def update() -> None:
    if not MAPPED:
        ALTAR_RING = altar_ring()
        SAFE_RING = safe_altar_ring()
        MONO_GROUPS = mono_groups()
        TERRAIN = walls() | holes() | altars() | enemy_spawn()
        BIG_CAMPS = type_spawns(MONOLITH) | type_spawns(GOLEM)
        CAMP_BASE = camp_spawns() - BIG_CAMPS - MONO_GROUPS
        SK0 = slot_kind(0)
        SK1 = slot_kind(1)
        MAPPED = True
    if not RICH_MAPPED and round() >= 3:
        RICH_BASE = CAMP_BASE & rich_groups()
        RICH_MAPPED = True
    BLOCK = blocked_now()
    RULE = rule()
    GOAL = rule_goal()
    TGT = rule_target()
    OPEN = False
    if walks() and valid(GOAL) and GOAL != here():
        OPEN = walk_open()
        FIELD = walk_field()
    LOCK_BUY = RULE >= 1 and at_spawn() and wants_lock()
    if LOCK_BUY:
        write_shared(7, read_shared(7) + 2)
